"""
Base strategy class for all trading strategies.
"""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from datetime import datetime
from typing import Optional
import logging

from ..models import Market, Order, Position, Strategy
from ..config import TradingConfig

logger = logging.getLogger(__name__)


@dataclass
class StrategySignal:
    """Signal generated by a strategy."""
    market_id: str
    action: str  # "buy_yes", "buy_no", "sell_yes", "sell_no", "hold"
    quantity: float = 0.0
    price: Optional[float] = None
    confidence: float = 0.0  # 0-1 confidence score
    reason: str = ""
    timestamp: datetime = field(default_factory=datetime.utcnow)

    @property
    def is_buy(self) -> bool:
        return self.action.startswith("buy")

    @property
    def is_sell(self) -> bool:
        return self.action.startswith("sell")


class BaseStrategy(ABC):
    """
    Abstract base class for trading strategies.

    All strategies must implement:
    - analyze(): Analyze market and generate signals
    - should_enter(): Determine if entry conditions are met
    - should_exit(): Determine if exit conditions are met
    """

    name: str = "base"
    strategy_type: Strategy = Strategy.MARKET_MAKER

    def __init__(self, config: TradingConfig):
        self.config = config
        self.active_positions: dict[str, Position] = {}
        self.signals: list[StrategySignal] = []

    @abstractmethod
    async def analyze(self, market: Market) -> Optional[StrategySignal]:
        """
        Analyze a market and generate trading signal.

        Args:
            market: Market to analyze

        Returns:
            StrategySignal if action needed, None otherwise
        """
        pass

    @abstractmethod
    def should_enter(self, market: Market) -> bool:
        """
        Determine if entry conditions are met for this market.

        Args:
            market: Market to evaluate

        Returns:
            True if should enter position
        """
        pass

    @abstractmethod
    def should_exit(self, position: Position, market: Market) -> bool:
        """
        Determine if exit conditions are met for a position.

        Args:
            position: Current position
            market: Market data

        Returns:
            True if should exit position
        """
        pass

    def calculate_position_size(
        self,
        capital: float,
        price: float,
        risk_percent: Optional[float] = None
    ) -> float:
        """
        Calculate appropriate position size based on risk management.

        Args:
            capital: Available capital
            price: Entry price
            risk_percent: Risk per trade (default from config)

        Returns:
            Number of shares to buy
        """
        if risk_percent is None:
            risk_percent = self.config.risk_per_trade

        risk_amount = capital * risk_percent
        position_size = risk_amount / price if price > 0 else 0

        return max(0, position_size)

    def add_position(self, position: Position):
        """Track a new position."""
        self.active_positions[position.id] = position
        logger.info(f"Position added: {position.id} in market {position.market_id}")

    def remove_position(self, position_id: str):
        """Remove a closed position."""
        if position_id in self.active_positions:
            del self.active_positions[position_id]
            logger.info(f"Position removed: {position_id}")

    def get_position_for_market(self, market_id: str) -> Optional[Position]:
        """Get active position for a specific market."""
        for position in self.active_positions.values():
            if position.market_id == market_id:
                return position
        return None

    def log_signal(self, signal: StrategySignal):
        """Log a generated signal."""
        self.signals.append(signal)
        logger.info(
            f"[{self.name}] Signal: {signal.action} for {signal.market_id} "
            f"(confidence: {signal.confidence:.2f}, reason: {signal.reason})"
        )
